const input = $json.body ?? $json;
if (typeof input.campaignId !== 'string' || !input.selectedPackage || typeof input.selectedPackage !== 'object') throw new Error('campaignId and selectedPackage are required');
return [{ json: input }];

const selected = $('Validate Creative Input').item.json.selectedPackage;
const creative = $json;
const campaign = selected.campaign;
const spotName = selected.spot?.name || 'Quiet Cup Cafe';
const allText = [creative.headline,creative.caption,creative.offerText,creative.callToAction,creative.providerBrief].filter(Boolean).join(' ').toLowerCase();
const issues = [];
const requireFact = (condition, code) => { if (!condition) issues.push(code); };
requireFact(allText.includes(spotName.toLowerCase()), 'incorrect_spot_name');
requireFact(allText.includes(campaign.slotStartAt.slice(0,10)) || allText.includes('friday'), 'incorrect_campaign_date');
requireFact(allText.includes('7') && allText.includes('9'), 'incorrect_campaign_time');
requireFact(Number(selected.discountBps) <= Number(campaign.maxDiscountBps), 'discount_above_limit');
requireFact(typeof creative.callToAction === 'string' && creative.callToAction.trim().length > 0, 'missing_cta');
requireFact(selected.packageId === (selected.approvedPackageId ?? selected.packageId), 'changed_package');
requireFact(Number(selected.exactPricePaise) === Number(selected.approvedAmountPaise ?? selected.exactPricePaise), 'changed_price');
requireFact(Number(selected.exactPricePaise) <= Number(campaign.maxBudgetPaise), 'exceeded_budget');
requireFact(Number(selected.worstCaseExpectedCpaPaise) <= Number(campaign.maxExpectedCpaPaise), 'high_cpa');
requireFact(Date.parse(selected.deadline) <= Date.parse(campaign.slotStartAt) && Date.now() <= Date.parse(selected.deadline), 'invalid_deadline');
requireFact(selected.recurringBilling !== true, 'recurring_payment');
return [{ json: { creative, deterministicApproved: issues.length === 0, deterministicIssues: issues, selected } }];

const deterministic = $('Run Deterministic Creative Checks').item.json;
const ai = $json;
const issues = [...deterministic.deterministicIssues, ...(ai.issues ?? []), ...(ai.unsupportedClaims ?? []).map((claim) => 'unsupported_claim:' + claim)];
return [{ json: { passed: deterministic.deterministicApproved && ai.approved === true && (ai.unsupportedClaims ?? []).length === 0, status: issues.length === 0 ? 'PASSED' : 'NEEDS_REVISION', issues, creative: deterministic.creative, selected: deterministic.selected, aiReview: ai } }];
